import { FC } from 'react';

import { FlexProps } from 'antd';
import cn from 'classnames';

import styles from './AdvCampaignCardSection.module.scss';

interface IAdvCampaignCardSectionProps extends FlexProps {
	padding?: number;
}

export const AdvCampaignCardSection: FC<IAdvCampaignCardSectionProps> = ({
	className,
	children,
	padding = 4,
	...props
}) => {
	return (
		<div {...props} style={{ padding: `${padding}px 8px` }} className={cn(className, styles.section)}>
			{children}
		</div>
	);
};
