import { FC, useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { Badge, Button, Flex, FlexProps, Tag, Typography } from 'antd';
import { RcFile } from 'antd/es/upload';
import cn from 'classnames';
import dayjs from 'dayjs';

import CrossIcon from 'assets/images/icons/cross.svg?react';
import { AdvCampaignCardSection } from 'entities/AdvCampaign';
import { EPaymentModel, EPaymentModelMap, useBrandSlice, useLazyAdvcampaignsRetrieveQuery } from 'entities/Brand';
import { usePostSlice } from 'entities/Post';
import { AutoDeletionAfterEnum, DeletePlannerPostModal, PlannerPost } from 'features/Planner';
import { EMainRoutes } from 'shared/typings';
import { ButtonStyleLink, OverlayLoader } from 'shared/ui';

import styles from './PlannerDayPost.module.scss';

interface IPlannerDayPostProps extends FlexProps {
	post: PlannerPost;
}

export const PlannerDayPost: FC<IPlannerDayPostProps> = ({ className, post, ...props }) => {
	const { t } = useTranslation();
	const paymentModel = EPaymentModel.CPA; //TODO: get from api
	const isPublished = post.channels?.some((channel) => channel.published_at);
	const [isDeleting, setIsDeleting] = useState(false);
	const { setIsOpenDetailsPopup, setAdvCampaign, setVisitedAdvCampaign, visitedAdvCampaigns } = useBrandSlice();
	const { setFormState, addImage } = usePostSlice();
	const [getAdvCampaign, { data: advCampaignDetails, isSuccess, isLoading }] = useLazyAdvcampaignsRetrieveQuery();

	const { advcampaign } = post;

	useEffect(() => {
		if (isSuccess) {
			setAdvCampaign(advCampaignDetails);
			setVisitedAdvCampaign(advCampaignDetails.uuid);
			setIsOpenDetailsPopup(true);
		}
	}, [isSuccess]); // eslint-disable-line react-hooks/exhaustive-deps

	const downloadImage = async (image: string) => {
		const response = await fetch(image);
		const blob = await response.blob();
		const fileReader = new FileReader();

		fileReader.addEventListener('load', () => {
			const name = image.split('/').pop();

			addImage({
				originFileObj: new File([blob], name || '') as unknown as RcFile,
				uid: Math.random().toString(36).substring(2, 15),
				name: name || '',
				preview: fileReader.result as string,
			});
		});

		fileReader.readAsDataURL(blob);
	};

	const onReschedule = async () => {
		Promise.all(post.images.map(downloadImage));

		setFormState({
			channel_ids: post.channels?.[0]?.id || null,
			date: dayjs(post.published_at),
			time: dayjs(post.published_at),
			auto_deletion_after: AutoDeletionAfterEnum.Never,
			publishNow: false,
			content: post.content,
			images: [],
		});
	};
	return (
		<Flex {...props} vertical className={cn(className, styles.card)} onClick={() => getAdvCampaign(advcampaign.id)}>
			{isLoading && <OverlayLoader />}
			<Flex align="start">
				<img className={styles.image} src={advcampaign.image} alt={advcampaign.name} />

				<Flex vertical gap={4} className={styles.info}>
					<Typography.Paragraph
						className={styles.title}
						style={{ margin: 0 }}
						strong
						type={visitedAdvCampaigns.includes(advcampaign.id) ? 'secondary' : undefined}
						ellipsis={{
							rows: 3,
						}}>
						{advcampaign.name}
					</Typography.Paragraph>

					<Flex gap={4}>
						<Tag color={EPaymentModelMap[paymentModel].color}>{EPaymentModelMap[paymentModel].text}</Tag>
					</Flex>
				</Flex>
			</Flex>

			<AdvCampaignCardSection>
				<Flex
					gap={4}
					justify={'space-between'}
					className={cn(styles.collectionPostCard__part, styles.collectionPostCard__schedule)}>
					{isPublished ? (
						<Badge status="success" text={t('Опубликовано')} />
					) : (
						<Badge status="processing" text={t('Опубликуется')} />
					)}
					<Flex gap={4} align="center">
						<Typography.Text type="secondary" style={{ fontSize: 12 }}>
							{new Date(post.published_at || '').toLocaleString('ru-RU', { hour: '2-digit', minute: '2-digit' })}
						</Typography.Text>
						<Typography.Text type="secondary" style={{ fontSize: 12 }}>
							•
						</Typography.Text>
						<Typography.Text type="secondary" style={{ fontSize: 12 }}>
							{new Date(post.published_at || '').toLocaleString('ru-RU', { day: '2-digit', month: 'short' })}
						</Typography.Text>
					</Flex>
				</Flex>
			</AdvCampaignCardSection>

			<AdvCampaignCardSection padding={8}>
				{!isPublished && (
					<Button
						onClick={() => setIsDeleting(true)}
						variant="outlined"
						color="danger"
						size="large"
						icon={<CrossIcon />}
						block>
						{t('Отменить публикацию')}
					</Button>
				)}
				{isPublished && (
					<ButtonStyleLink
						to={`/${EMainRoutes.POST}/${post.advcampaign.id}`}
						onClick={onReschedule}
						size="large"
						className={styles.button}
						block>
						{t('Запланировать повторно')}
					</ButtonStyleLink>
				)}
			</AdvCampaignCardSection>

			<DeletePlannerPostModal post={post} open={isDeleting} onCancel={() => setIsDeleting(false)} />
		</Flex>
	);
};
