import { FC, useEffect } from 'react';
import { useTranslation } from 'react-i18next';

import { Modal, ModalProps, notification } from 'antd';

import { PlannerPost, usePlannerPostsDestroyMutation } from 'features/Planner';

interface IDeletePlannerPostModalProps extends ModalProps {
	post: PlannerPost;
}

export const DeletePlannerPostModal: FC<IDeletePlannerPostModalProps> = ({ post, onCancel, ...props }) => {
	const { t } = useTranslation();
	const [deletePost, { isLoading, isSuccess }] = usePlannerPostsDestroyMutation();

	useEffect(() => {
		if (isSuccess) {
			onCancel?.({} as React.MouseEvent<HTMLButtonElement>);
			notification.success({
				message: t('Пост успешно удален'),
				placement: 'bottom',
				showProgress: true,
				pauseOnHover: true,
			});
		}
	}, [isSuccess, onCancel, t]);

	return (
		<Modal
			{...props}
			okType="danger"
			okText={t('Удалить')}
			cancelText={t('Отмена')}
			onOk={() => {
				deletePost(post.id);
			}}
			onCancel={onCancel}
			title={t('Вы уверены, что хотите удалить запланированный пост?')}
			styles={{
				header: {
					padding: '24px 0 12px',
				},
			}}
			okButtonProps={{
				loading: isLoading,
				disabled: isLoading,
			}}
		/>
	);
};
